import {useEffect,useState} from 'react';
import {api} from '../lib/backend';
export function OCRSettings({onDone}:{onDone?:()=>void}){
 const [provider,setProvider]=useState('llamaparse'),[key,setKey]=useState(''),[credentials,setCredentials]=useState<Record<string,boolean>>({}),[busy,setBusy]=useState(false),[error,setError]=useState(''),[message,setMessage]=useState('');
 useEffect(()=>{void api<any>('/api/ocr/config').then(c=>{setProvider(c.provider==='none'?'llamaparse':c.provider);setCredentials(c.credentials||{});}).catch(e=>setError(String(e)));},[]);
 const cloud=['llamaparse','google-vision'].includes(provider);
 const save=async(selected=provider)=>{setBusy(true);setError('');try{await api('/api/admin/ocr',{method:'PUT',body:JSON.stringify({provider:selected,key:selected===provider?key:''})});setKey('');setCredentials(c=>({...c,[selected]:true}));setMessage('OCR settings saved.');onDone?.();}catch(e){setError(e instanceof Error?e.message:String(e));}finally{setBusy(false);}};
 return <div><h2>Choose your OCR provider</h2><p>These settings apply to this installation. Cloud OCR sends scan images to the selected service. API keys stay in private configuration on this computer.</p><label>OCR service<select aria-label="OCR service" disabled={busy} value={provider} onChange={e=>{setProvider(e.target.value);setKey('');setMessage('');}}><option value="llamaparse">LlamaParse / LlamaCloud</option><option value="google-vision">Google Cloud Vision</option><option value="tesseract">Tesseract — offline (optional)</option></select></label>{cloud&&<><label>{provider==='llamaparse'?'LLAMA_CLOUD_API_KEY':'GOOGLE_VISION_API_KEY'}<input type="password" autoComplete="off" value={key} disabled={busy} placeholder={credentials[provider]?'Key already configured; leave empty to keep it':'Enter your API key'} onChange={e=>setKey(e.target.value)}/></label><p className="field-help">{provider==='google-vision'?'Enable the Cloud Vision API and billing in your Google Cloud project.':'Use an API key from your LlamaCloud account.'}</p></>}{provider==='tesseract'&&<p className="field-help">Runs locally. Initialization times out after 60 seconds; each page has a 5 minute limit. Cancel now stops the worker.</p>}<div className="button-row"><button type="button" className="button primary" disabled={busy||(cloud&&!key&&!credentials[provider])} onClick={()=>void save()}>{busy?'Saving…':'Save OCR provider'}</button>{onDone&&<button type="button" className="button secondary" disabled={busy} onClick={()=>void save('none')}>Configure later</button>}</div>{error&&<p className="error-list" role="alert">{error}</p>}{message&&<p role="status">{message}</p>}</div>;
}
