import { ApplicationCopyright } from '../components/Brand';
import { useEffect, useState } from 'react';
import type { CatalogBook } from '../lib/catalog';
import { createBook, renameLibraryBook, abandonBook, purgeBook } from '../lib/catalog';
import { collectionBooks, collectionSummary, type CollectionFilter } from '../lib/collection';
import { formatPublishedAt } from '../lib/reading';
import { Icon } from '../components/Icon';
import { Modal } from '../components/Modal';
import { currentAccount, serverStorage } from '../lib/backend';
import { StorageCheck } from '../components/StorageCheck';
import { WorkspaceHeader, type Navigate } from './WorkspaceHeader';
function Cover({ book }: { book: CatalogBook }) {
    const [url, setUrl] = useState('');
    useEffect(() => { if (!book.cover) { setUrl(''); return; } const u = URL.createObjectURL(book.cover); setUrl(u); return () => URL.revokeObjectURL(u); }, [book.cover]);
    return <div className={`library-cover ${url ? 'has-scan' : ''}`}>{url ? <img src={url} alt={`Cover page of ${book.title}`}/> : <><Icon name="book" size={36}/><strong>{book.title}</strong><span>{book.year || 'Scanned edition'}</span></>}<span className="cover-spine"/></div>;
}
export function LibraryHome({ books, preparation, navigate, setLocked }: { books: CatalogBook[]; preparation: boolean; navigate: Navigate; setLocked: (b: boolean) => void }) {
    const [query, setQuery] = useState(''), [sort, setSort] = useState('recent'), [filter, setFilter] = useState<CollectionFilter>('all');
    const [newBook, setNewBook] = useState(false), [title, setTitle] = useState(''), [busy, setBusy] = useState(false), [error, setError] = useState('');
    const [editing, setEditing] = useState<CatalogBook | null>(null);
    useEffect(() => { setLocked(Boolean(editing || newBook || busy)); return () => setLocked(false); }, [editing, newBook, busy, setLocked]);
    const rename = async () => { if (!editing) return; setBusy(true); setError(''); try { await renameLibraryBook(editing.id, title, editing.title); setEditing(null); } catch (e) { setError(String(e)); } finally { setBusy(false); } };
    const { saved, published, drafts, abandoned, pageCount } = collectionSummary(books);
    const lifecycle = async (book: CatalogBook, action: 'abandon' | 'resume' | 'purge') => {
        if (action === 'purge' && !confirm(`Permanently purge “${book.title}”? Its scans, text, bookmarks, highlights and notes will be deleted. Other books are unaffected. Export a backup first if needed.`)) return;
        setBusy(true); setError('');
        try { if (action === 'purge') await purgeBook(book.id); else await abandonBook(book.id, action === 'abandon'); }
        catch (e) { setError(String(e)); } finally { setBusy(false); }
    };
    const list = collectionBooks(books, filter, query, sort);
    const openBook = (book: CatalogBook) => !preparation && (book.status === 'published' || book.publishedAvailable) ? navigate(`/read/${book.id}`) : book.abandoned ? void resume(book) : navigate(`/preparation/${book.id}`);
    const resume = async (book: CatalogBook) => {
        setBusy(true); setError('');
        try { await abandonBook(book.id, false); setLocked(false); navigate(`/preparation/${book.id}`); }
        catch (e) { setError(String(e)); } finally { setBusy(false); }
    };
    useEffect(() => { document.title = `${preparation ? 'Book Preparation' : 'Library'} · OM Daily Reading`; }, [preparation]);
    const create = async () => { setBusy(true); setLocked(true); setError(''); try { const book = await createBook(title); setNewBook(false); setLocked(false); navigate(`/preparation/${book.id}`); } catch(e) { setError(String(e)); } finally { setBusy(false); setLocked(false); } };
    return <div className="app theme-paper workspace-app"><WorkspaceHeader active={preparation ? 'preparation' : 'library'} navigate={navigate}/><main className="workspace-scroll"><div className="collection-content">
        <section className="collection-hero"><div><span className="eyebrow">{preparation ? '01 / PREPARE & PUBLISH' : '02 / READ & REMEMBER'}</span><h1>{preparation ? 'Book Preparation' : 'Your library'}</h1><p>{preparation ? 'A dedicated workspace for injection, OCR, page order and verification. Publish when the book is ready.' : 'All your saved books, including imports in preparation and abandoned drafts. Published books are ready to read.'}</p></div>{preparation && currentAccount?.role!=='reader' ? <button className="button primary" onClick={() => { setTitle(''); setError(''); setNewBook(true); }}><Icon name="plus" size={18}/>New book</button> : <div className="collection-total"><strong>{saved.length}</strong><span>{saved.length === 1 ? 'saved book' : 'saved books'}</span></div>}</section>
        <div className="collection-metrics"><span><strong>{published.length}</strong> Ready to read</span><span><strong>{drafts.length}</strong> In preparation</span><span><strong>{abandoned.length}</strong> Abandoned · saved</span><span><strong>{pageCount}</strong> Saved pages</span></div>
        {abandoned.length > 0 && <div className="collection-lifecycle-note"><Icon name="folder" size={18}/><p>Abandoned preparations are still saved. Choose <strong>Resume preparation</strong> on a book to continue. Abandoning does not delete its pages.</p></div>}
        {error && !newBook && !editing && <p className="error-list" role="alert">{error}</p>}
        {!saved.length && serverStorage() && <p className="field-help">{currentAccount?.role==='reader'?'No published books have been granted to your account. Ask your administrator for access.':'Your shared library is empty. Create a book or migrate existing browser books from Administration.'}</p>}
        {!saved.length && !serverStorage() && <p className="field-help">No imported books were found in this browser at <strong>{location.origin}</strong>. If you imported elsewhere, open the original browser and exact address, including the port. Existing bundled samples are listed separately in the status filter.</p>}
        <div className="collection-tools"><div className="collection-search"><Icon name="search" size={18}/><input aria-label="Search book library" placeholder="Search saved books by title, author or edition…" value={query} onChange={e => setQuery(e.target.value)}/></div><select aria-label="Filter book status" value={filter} onChange={e => setFilter(e.target.value as CollectionFilter)}><option value="all">All saved books ({saved.length})</option><option value="published">Ready to read ({published.length})</option><option value="draft">In preparation ({drafts.length})</option><option value="abandoned">Abandoned ({abandoned.length})</option>{books.some(b => b.sample && !b.purged) && <option value="sample">Bundled samples</option>}</select><select aria-label="Sort library" value={sort} onChange={e => setSort(e.target.value)}><option value="recent">Recently opened</option><option value="title">Title: A–Z</option><option value="published">Recently published</option></select></div>
        {list.length ? <div className="book-grid">{list.map(book => <article className="library-card" key={book.id}><button className="book-cover-button" aria-label={`${book.abandoned ? 'Resume preparation for' : book.status === 'draft' || preparation ? 'Prepare' : 'Read'} ${book.title}`} disabled={busy} onClick={() => openBook(book)}><Cover book={book}/></button><div className="library-card-body">{book.publishedAvailable&&book.status==='draft'&&<button className="button primary full" onClick={()=>navigate(`/read/${book.id}`)}>Read published edition</button>}<div className="book-card-status"><span className={`status-pill ${book.abandoned ? 'abandoned' : book.status}`}>{book.abandoned ? 'Abandoned' : book.status === 'published' ? 'Ready to read' : 'In preparation'}</span><span>{book.pageCount} pages</span></div>{book.sample && <p className="field-help">Bundled sample · not your imported edition</p>}<h2><button disabled={busy} onClick={() => openBook(book)}>{book.title}</button></h2><p className="book-card-description">{book.author || book.subtitle || (book.year ? `Edition ${book.year}` : 'Your digitized edition')}</p>
            {book.status === 'published' && <p className="book-published-date"><Icon name="calendar" size={14}/><span>{book.publishedAt ? 'Published to library · ' : ''}{formatPublishedAt(book.publishedAt)}</span></p>}
            {!preparation && book.status === 'published' && book.canPrepare!==false && <button className="text-button edit-library-title" aria-label={`Edit title for ${book.title}`} onClick={() => { setEditing(book); setTitle(book.title); setError(''); }}><Icon name="edit" size={14}/>Edit book title</button>}
            {preparation || book.status === 'draft' ? <><div className="book-mini-stats"><span>{book.searchableCount} searchable</span><span>{book.approvedCount} approved</span></div><button disabled={busy} className="button secondary full" onClick={() => book.abandoned ? void resume(book) : openBook(book)}>{book.abandoned ? 'Resume preparation' : book.status === 'published' ? 'Publication details' : 'Continue preparation'}<Icon name="right" size={16}/></button>{book.status === 'draft' && book.canPrepare!==false && <div className="button-row">{!book.abandoned && <button disabled={busy} className="text-button" onClick={() => void lifecycle(book, 'abandon')}>Abandon preparation</button>}{!book.publishedAvailable&&<button disabled={busy} className="text-button" onClick={() => void lifecycle(book, 'purge')}>Purge book</button>}</div>}</> : <><div className="book-reading-status"><span>{book.readCount ? `${book.readCount} of ${book.pageCount} pages read` : 'Start your reading'}</span><span>{book.pageCount ? Math.round(book.readCount/book.pageCount*100) : 0}%</span></div><div className="progress-track"><div style={{width: `${book.pageCount ? book.readCount/book.pageCount*100 : 0}%`}}/></div><div className="book-mini-stats"><span><Icon name="bookmark" size={13}/>{book.bookmarkCount} bookmarks</span><span><Icon name="note" size={13}/>{book.annotationCount} notes / highlights</span></div><button className="button primary full" onClick={() => navigate(`/read/${book.id}`)}>{book.lastPageTitle ? 'Continue reading' : 'Open book'}<Icon name="right" size={16}/></button></>}
        </div></article>)}</div> : <div className="collection-empty"><Icon name={query ? 'search' : 'book'} size={44}/><h2>{query ? 'No matching books' : saved.length || filter === 'sample' ? 'No books in this view' : 'Start your book collection'}</h2><p>{query ? 'Try a different title, author or edition.' : saved.length ? 'Choose All saved books to see your drafts, published books and abandoned preparations.' : 'Create a book in Book Preparation and import your scans. It appears here immediately; publication is required only to open the reader.'}</p>{!saved.length && filter !== 'sample' && currentAccount?.role!=='reader' && <button className="button primary" onClick={() => navigate('/preparation')}>Go to Book Preparation<Icon name="right" size={16}/></button>}</div>}
        {!serverStorage()&&<StorageCheck/>}
        <footer className="collection-footer"><span><Icon name="lock" size={13}/>Saved in the shared library · Keep external backups</span><span>{preparation ? 'Preparation does not change your original scan files.' : 'Reading appearance, bookmarks and notebook are inside each book.'}</span></footer>
    <ApplicationCopyright/></div></main>{newBook && <Modal title="Create a book" description="Each book has its own scans, page order, text and personal reading data." onClose={() => !busy && setNewBook(false)} locked={busy}><label>Book title<input autoFocus maxLength={1000} value={title} onChange={e => setTitle(e.target.value)} onKeyDown={e => { if (e.key === 'Enter' && title.trim() && !busy) void create(); }}/></label><p className="field-help">Creating a new book does not replace your existing book. You can import images or restore an OM book backup into it.</p>{error && <p className="error-list" role="alert">{error}</p>}<div className="modal-footer"><button className="button secondary" disabled={busy} onClick={() => setNewBook(false)}>Cancel</button><button className="button primary" disabled={busy || !title.trim()} onClick={() => void create()}>{busy ? 'Creating…' : 'Create book'}</button></div></Modal>}{editing && <Modal title="Edit library title" description="This changes the title everywhere in the reader, without changing your pages, personal notes, or publication date." onClose={() => !busy && setEditing(null)} locked={busy}><label>Book title<input aria-label="Library book title" autoFocus maxLength={1000} value={title} onChange={e => setTitle(e.target.value)} onKeyDown={e => { if (e.key === 'Enter' && title.trim() && !busy) void rename(); }}/></label><p className="field-help">Published to library: {formatPublishedAt(editing.publishedAt)}</p>{error && <p className="error-list" role="alert">{error}</p>}<div className="modal-footer"><button className="button secondary" disabled={busy} onClick={() => setEditing(null)}>Cancel</button><button className="button primary" disabled={busy || !title.trim()} onClick={() => void rename()}>{busy ? 'Saving…' : 'Save title'}</button></div></Modal>}</div>;
}
