import type { Preferences } from '../types';
import { NARRATORS, resolveBrowserVoice } from '../lib/narration';
import { Icon } from '../components/Icon';
import type { NarrationController } from './useNarration';
export function NarrationPanel({ prefs, control, onPrefs, onPlay, onToday, todayCount, onClose }: {
    prefs: Preferences; control: NarrationController; onPrefs: (patch: Partial<Preferences>) => void;
    onPlay: () => void; onToday: () => void; todayCount: number; onClose: () => void;
}) {
    const engine = prefs.narrationEngine || 'browser', status = control.playback.status;
    const change = (patch: Partial<Preferences>) => { control.stop(); onPrefs(patch); };
    return <section className="narration-panel" aria-label="Read aloud settings">
        <div className="narration-heading"><div><Icon name="headphones" size={20}/><strong>Listen to your book</strong></div><button className="icon-button" aria-label="Close read aloud settings" onClick={onClose}><Icon name="close"/></button></div>
        <div className="narration-options"><label>Voice source<select value={engine} onChange={e => change({ narrationEngine:e.target.value as 'browser' | 'azure', narrationVoiceURI:'' })}><option value="browser">Device voices</option><option value="azure">Neural voices · Azure</option></select></label><label>Reading speed<select value={prefs.narrationRate || .95} onChange={e => change({ narrationRate:Number(e.target.value) })}>{[.75,.85,.95,1,1.1,1.25,1.5].map(rate => <option key={rate} value={rate}>{rate}×{rate === .95 ? ' · relaxed' : ''}</option>)}</select></label></div>
        <div className="voice-grid">{NARRATORS.map(n => {
            const mapped = resolveBrowserVoice(control.voices, n.id), selected = (prefs.narrationPreset || 'us-female') === n.id && !prefs.narrationVoiceURI;
            const available = engine === 'azure' ? control.cloudReady : !!mapped;
            return <button key={n.id} className={`voice-card ${selected ? 'selected' : ''}`} aria-pressed={selected} onClick={() => change({ narrationPreset:n.id, narrationVoiceURI:'' })}><span>{n.label}</span><strong>{engine === 'azure' ? n.name : mapped?.name || 'No matching device voice'}</strong><small>{engine === 'azure' ? (control.cloudReady ? 'Neural narrator' : 'Server setup required') : available ? 'Available device voice' : 'Choose an available voice below'}</small></button>;
        })}</div>
        {engine === 'browser' ? <><label>Installed voice override<select aria-label="Installed voice override" value={prefs.narrationVoiceURI || ''} onChange={e => change({ narrationVoiceURI:e.target.value })}><option value="">Use the matching preset voice</option>{control.voices.map((voice,i) => <option key={`${voice.voiceURI}-${i}`} value={voice.voiceURI}>{voice.name} · {voice.lang}{voice.localService ? ' · device' : ' · online'}</option>)}</select></label><p className="field-help">Device voices depend on your browser and operating system. The reader never substitutes one voice for four different speakers. Voices marked “online” may send text to their provider.</p></> : <><label className="automation-choice"><input type="checkbox" checked={!!prefs.narrationCloudConsent} onChange={e => change({ narrationCloudConsent:e.target.checked })}/><span>Allow the spoken text to be sent to Azure Speech when I press Play. Provider charges may apply; my notes and scans are not sent.</span></label>{!control.cloudReady && <p className="narration-warning">The four neural narrators need your Azure Speech key and region on the server. See <code>docs/READING-UPGRADE.md</code>. Device voices remain available without this setup.</p>}</>}
        <div className="narration-automation"><label className="automation-choice"><input type="checkbox" checked={prefs.narrationFollow !== false} onChange={e => onPrefs({ narrationFollow:e.target.checked })}/><span>Follow the narrated page automatically</span></label><label className="automation-choice"><input type="checkbox" checked={!!prefs.autoOpenToday} onChange={e => onPrefs({ autoOpenToday:e.target.checked })}/><span>Open this book at today's dated reading</span></label></div>
        <div className="narration-controls"><button className="button primary" disabled={!control.available} onClick={status === 'playing' || status === 'loading' ? control.pause : status === 'paused' ? control.resume : onPlay}><Icon name={status === 'playing' || status === 'loading' ? 'pause' : 'play'} size={17}/>{status === 'playing' || status === 'loading' ? 'Pause' : status === 'paused' ? 'Resume' : 'Read from here'}</button><button className="button secondary" disabled={!control.available || !todayCount} onClick={onToday}><Icon name="calendar" size={16}/>Listen today</button><button className="button secondary" disabled={!control.available} onClick={control.preview}>Preview voice</button></div>
        <p className="field-help">Read from here continues in book order. Listen today reads only pages matching today's printed month and day, then stops. Audio begins after you press Play—not silently on page load.</p>
    </section>;
}
